package com.zhou.craft.repo;import com.zhou.craft.model.CraftWork;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*;
public interface CraftWorkRepository extends JpaRepository<CraftWork,Long>{List<CraftWork> findByFeaturedTrueAndStatusOrderByLikesDesc(String status);List<CraftWork> findByCategoryIgnoreCaseAndStatus(String category,String status);List<CraftWork> findByStatusOrderByIdDesc(String status);List<CraftWork> findByCreatorIdOrderByIdDesc(Long creatorId);Optional<CraftWork> findByTitle(String title);}